/// <summary>
/// Add Report to Print Management configuration
/// </summary>
protected void addDocuments()
{
    this.addOther(PrintMgmtDocumentType::SalesFreeTextInvoice, ssrsReportStr(METFreeTextInvoiceRebate, Report), ssrsReportStr(METFreeTextInvoiceRebate, Report), #NoCountryRegionId);

    this.addOther(PrintMgmtDocumentType::PurchaseOrderReceiptsList, ssrsReportStr(METPurchReceiptsList, Report), ssrsReportStr(METPurchReceiptsList, Report), #NoCountryRegionId);
    next addDocuments();
}
